// Vendor app icon set — one stroke family (Lucide geometry, 24px grid, 1.75 stroke)
function Icon({ className = "w-5 h-5", strokeWidth = 1.75, children, ...rest }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      {children}
    </svg>
  );
}

